insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-191', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'First ionisation enthalpy falls in the order Li > Na > K because', '["nuclear charge falls down the group","atomic size increases down the group","the number of valence electrons increases","they become noble gases"]'::jsonb, 1, 'The ns¹ electron is farther from the nucleus and more shielded in Na and K than in Li.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'ionization-enthalpy') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
