insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-193', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Boron has a lower first ionisation enthalpy than beryllium even though B is smaller, because', '["the 2p electron of B is shielded by 2s² and is easier to remove than a 2s electron of Be","boron has a noble-gas configuration","beryllium has a half-filled 2p set","nuclear charge falls from Be to B"]'::jsonb, 0, 'The two trends conflict: smaller size would raise IE, but the change of subshell (2s → 2p) lowers it, and the subshell effect wins.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'ionization-enthalpy') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
