insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-194', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'For magnesium, the jump between IE₂ and IE₃ is much larger than between IE₁ and IE₂ because the third electron', '["comes from the 3s subshell","comes from the neon core","is a 3p electron of Al","enters a 4s orbital"]'::jsonb, 1, 'Mg is 3s², so IE₁ and IE₂ remove valence electrons; IE₃ must break the 2p⁶ core and is therefore very large.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'ionization-enthalpy') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
